import { onScopeDispose, ref } from "vue";

export interface RecordedAudio {
  name: string;
  mimeType: string;
  dataUrl: string;
  durationMs: number;
}

interface AudioRecorderOptions {
  maxMs?: number;
  bars?: number;
  onAutoStop?: (clip: RecordedAudio) => void;
}

const DEFAULT_MAX_MS = 60_000;
const DEFAULT_BARS = 44;
const SAMPLE_INTERVAL_MS = 55;

function pickMimeType(): string {
  const candidates = ["audio/webm;codecs=opus", "audio/webm", "audio/mp4", "audio/ogg"];
  if (typeof MediaRecorder === "undefined") return "audio/webm";
  for (const type of candidates) {
    if (MediaRecorder.isTypeSupported(type)) return type;
  }
  return "audio/webm";
}

function blobToDataUrl(blob: Blob): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result as string);
    reader.onerror = () => reject(reader.error);
    reader.readAsDataURL(blob);
  });
}

export function useAudioRecorder(options: AudioRecorderOptions = {}) {
  const maxMs = options.maxMs ?? DEFAULT_MAX_MS;
  const barCount = options.bars ?? DEFAULT_BARS;

  const supported =
    typeof navigator !== "undefined" &&
    !!navigator.mediaDevices?.getUserMedia &&
    typeof MediaRecorder !== "undefined";

  const recording = ref(false);
  const levels = ref<number[]>(Array.from({ length: barCount }, () => 0));
  const elapsedLabel = ref("0:00");

  let stream: MediaStream | null = null;
  let recorder: MediaRecorder | null = null;
  let audioContext: AudioContext | null = null;
  let analyser: AnalyserNode | null = null;
  let source: MediaStreamAudioSourceNode | null = null;
  let chunks: Blob[] = [];
  let rafId = 0;
  let maxTimer: ReturnType<typeof setTimeout> | null = null;
  let startedAt = 0;
  let lastSample = 0;
  let activeMime = "audio/webm";
  let discarded = false;
  let stopResolvers: ((blob: Blob | null) => void)[] = [];

  function teardown() {
    if (rafId) cancelAnimationFrame(rafId);
    rafId = 0;
    if (maxTimer) clearTimeout(maxTimer);
    maxTimer = null;
    source?.disconnect();
    source = null;
    analyser = null;
    if (audioContext && audioContext.state !== "closed") void audioContext.close();
    audioContext = null;
    stream?.getTracks().forEach((track) => track.stop());
    stream = null;
    recorder = null;
  }

  function resetVisuals() {
    levels.value = Array.from({ length: barCount }, () => 0);
    elapsedLabel.value = "0:00";
  }

  function formatElapsed(ms: number): string {
    const total = Math.floor(ms / 1000);
    const minutes = Math.floor(total / 60);
    const seconds = total % 60;
    return `${minutes}:${String(seconds).padStart(2, "0")}`;
  }

  function tick() {
    if (!analyser) return;
    const now = performance.now();
    elapsedLabel.value = formatElapsed(now - startedAt);

    if (now - lastSample >= SAMPLE_INTERVAL_MS) {
      lastSample = now;
      const buffer = new Uint8Array(analyser.frequencyBinCount);
      analyser.getByteTimeDomainData(buffer);
      let sum = 0;
      for (const value of buffer) {
        const deviation = (value - 128) / 128;
        sum += deviation * deviation;
      }
      const rms = Math.sqrt(sum / buffer.length);
      const normalized = Math.min(1, rms * 3.2);
      const next = levels.value.slice(1);
      next.push(normalized);
      levels.value = next;
    }

    rafId = requestAnimationFrame(tick);
  }

  function buildClip(blob: Blob): Promise<RecordedAudio> {
    const durationMs = Math.round(performance.now() - startedAt);
    return blobToDataUrl(blob).then((dataUrl) => ({
      name: `voice-${Date.now()}.${activeMime.includes("mp4") ? "m4a" : "webm"}`,
      mimeType: activeMime.split(";")[0] ?? "audio/webm",
      dataUrl,
      durationMs,
    }));
  }

  async function start(): Promise<boolean> {
    if (!supported || recording.value) return false;
    try {
      stream = await navigator.mediaDevices.getUserMedia({ audio: true });
    } catch {
      return false;
    }

    discarded = false;
    chunks = [];
    activeMime = pickMimeType();
    resetVisuals();

    const Ctx =
      window.AudioContext ??
      (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
    audioContext = new Ctx();
    analyser = audioContext.createAnalyser();
    analyser.fftSize = 256;
    source = audioContext.createMediaStreamSource(stream);
    source.connect(analyser);

    recorder = new MediaRecorder(stream, { mimeType: activeMime, audioBitsPerSecond: 32000 });
    recorder.ondataavailable = (event) => {
      if (event.data.size > 0) chunks.push(event.data);
    };
    recorder.onstop = () => {
      const blob = discarded ? null : new Blob(chunks, { type: activeMime });
      const resolvers = stopResolvers;
      stopResolvers = [];
      teardown();
      recording.value = false;
      for (const resolve of resolvers) resolve(blob);
    };

    recorder.start();
    recording.value = true;
    startedAt = performance.now();
    lastSample = 0;
    rafId = requestAnimationFrame(tick);

    maxTimer = setTimeout(() => {
      void finishInternal().then((clip) => {
        if (clip) options.onAutoStop?.(clip);
      });
    }, maxMs);

    return true;
  }

  function stopRecorder(): Promise<Blob | null> {
    if (!recorder || recorder.state === "inactive") {
      teardown();
      recording.value = false;
      resetVisuals();
      return Promise.resolve(null);
    }
    return new Promise((resolve) => {
      stopResolvers.push(resolve);
      recorder?.stop();
    });
  }

  async function finishInternal(): Promise<RecordedAudio | null> {
    if (!recording.value) return null;
    discarded = false;
    const blob = await stopRecorder();
    resetVisuals();
    if (!blob || blob.size === 0) return null;
    return buildClip(blob);
  }

  async function finish(): Promise<RecordedAudio | null> {
    if (maxTimer) clearTimeout(maxTimer);
    maxTimer = null;
    return finishInternal();
  }

  function cancel() {
    if (!recording.value) return;
    discarded = true;
    void stopRecorder().then(() => resetVisuals());
  }

  onScopeDispose(() => {
    discarded = true;
    if (recorder && recorder.state !== "inactive") recorder.stop();
    teardown();
  });

  return { supported, recording, levels, elapsedLabel, start, finish, cancel };
}
