<template>
  <div class="relative shrink-0" :class="compact ? 'h-9 w-9' : 'h-12 w-12'">
    <img
      v-if="imageUrl"
      :src="imageUrl"
      :alt="name"
      class="rounded-full object-cover"
      :class="compact ? 'h-9 w-9' : 'h-12 w-12'"
    />
    <div
      v-else
      class="flex items-center justify-center rounded-full bg-[#e6eefc] font-[760] text-[#1f6df5]"
      :class="compact ? 'h-9 w-9 text-[12px]' : 'h-12 w-12 text-[15px]'"
    >
      <ILucideUsers v-if="channelType === 'channel'" :class="compact ? 'h-4 w-4' : 'h-5 w-5'" />
      <span v-else>{{ initials }}</span>
    </div>
    <span
      v-if="online && channelType === 'chat'"
      class="absolute bottom-0 right-0 rounded-full border-2 border-white bg-[#2bb673]"
      :class="compact ? 'h-2.5 w-2.5' : 'h-3 w-3'"
    />
  </div>
</template>

<script setup lang="ts">
import { computed } from "vue";
import { channelInitials } from "../messenger.format";

const props = defineProps<{
  name: string;
  imageUrl: string | null;
  channelType: "channel" | "chat";
  compact?: boolean;
  online?: boolean;
}>();

const initials = computed(() => channelInitials(props.name));
</script>
