<template>
  <div class="flex w-[224px] max-w-full items-center gap-2.5 py-0.5">
    <div
      role="button"
      class="flex !h-9 !w-9 shrink-0 items-center justify-center rounded-full"
      :class="mine ? 'bg-white/25 text-white' : 'bg-[#1f6df5] text-white'"
      @click="toggle"
    >
      <ILucideLoader v-if="loading" class="h-4 w-4 animate-spin" />
      <ILucidePause v-else-if="playing" class="h-4 w-4" />
      <ILucidePlay v-else class="ml-0.5 h-4 w-4" />
    </div>

    <div class="min-w-0 flex-1">
      <div ref="track" class="flex h-7 cursor-pointer items-center gap-[2px]" @click="seek">
        <span
          v-for="(height, index) in waveform"
          :key="index"
          class="w-[3px] shrink-0 rounded-full transition-colors"
          :class="
            index / waveform.length <= progress / 100
              ? mine
                ? 'bg-white'
                : 'bg-[#1f6df5]'
              : mine
                ? 'bg-white/35'
                : 'bg-[#c2d4f1]'
          "
          :style="{ height: height + 'px' }"
        />
      </div>
    </div>
  </div>
</template>

<script setup lang="ts">
import { computed, onBeforeUnmount, ref } from "vue";

const props = defineProps<{ src: string; mine: boolean }>();

const BAR_COUNT = 36;
const waveform = computed(() => {
  let seed = 0;
  for (let i = 0; i < props.src.length; i += 1) seed = (seed * 31 + props.src.charCodeAt(i)) >>> 0;
  return Array.from({ length: BAR_COUNT }, (_, i) => {
    const n = Math.abs(Math.sin((i + 1) * 1.7 + seed));
    return Math.round(5 + n * 21);
  });
});

const audio = new Audio();
audio.preload = "metadata";
audio.src = props.src;

const playing = ref(false);
const loading = ref(false);
const progress = ref(0);
const current = ref(0);
const duration = ref(0);
const track = ref<HTMLElement | null>(null);

function fmt(seconds: number): string {
  if (!Number.isFinite(seconds) || seconds < 0) return "0:00";
  const m = Math.floor(seconds / 60);
  const s = Math.floor(seconds % 60);
  return `${m}:${String(s).padStart(2, "0")}`;
}

const timeLabel = ref("0:00");

function refreshLabel() {
  timeLabel.value = playing.value || current.value > 0 ? fmt(current.value) : fmt(duration.value);
}

function resolveDuration() {
  if (audio.duration === Infinity || Number.isNaN(audio.duration)) {
    audio.currentTime = 1e101;
    audio.addEventListener(
      "timeupdate",
      function onSeek() {
        audio.removeEventListener("timeupdate", onSeek);
        audio.currentTime = 0;
        duration.value = Number.isFinite(audio.duration) ? audio.duration : 0;
        refreshLabel();
      },
      { once: true },
    );
  } else {
    duration.value = audio.duration;
    refreshLabel();
  }
}

audio.addEventListener("loadedmetadata", resolveDuration);
audio.addEventListener("timeupdate", () => {
  current.value = audio.currentTime;
  progress.value = duration.value ? (audio.currentTime / duration.value) * 100 : 0;
  refreshLabel();
});
audio.addEventListener("ended", () => {
  playing.value = false;
  current.value = 0;
  progress.value = 0;
  refreshLabel();
});
audio.addEventListener("playing", () => {
  loading.value = false;
  playing.value = true;
});
audio.addEventListener("pause", () => {
  playing.value = false;
});
audio.addEventListener("waiting", () => {
  loading.value = true;
});

function toggle() {
  if (playing.value) {
    audio.pause();
    return;
  }
  loading.value = true;
  void audio.play().catch(() => {
    loading.value = false;
  });
}

function seek(event: MouseEvent) {
  if (!track.value || !duration.value) return;
  const rect = track.value.getBoundingClientRect();
  const ratio = Math.max(0, Math.min(1, (event.clientX - rect.left) / rect.width));
  audio.currentTime = ratio * duration.value;
}

onBeforeUnmount(() => {
  audio.pause();
  audio.src = "";
});
</script>
