import { computed, ref } from "vue";
import type { SendAttachmentInput } from "@aybsig/messenger";

interface PickedImage extends SendAttachmentInput {
  id: string;
}

export function useMessengerComposer(
  send: (text: string, attachments: SendAttachmentInput[]) => Promise<void>,
  isSending: () => boolean,
) {
  const text = ref("");
  const picked = ref<PickedImage[]>([]);

  const placeholder = computed(() =>
    picked.value.length > 0 ? "Add a caption or send" : "Message",
  );
  const hasInput = computed(() => text.value.trim().length > 0 || picked.value.length > 0);
  const canSend = computed(() => hasInput.value && !isSending());

  function readAsDataUrl(file: File): Promise<string> {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = () => resolve(reader.result as string);
      reader.onerror = () => reject(reader.error);
      reader.readAsDataURL(file);
    });
  }

  async function addFiles(files: File[]) {
    for (const [index, file] of files.entries()) {
      if (!file.type.startsWith("image/")) continue;
      const dataUrl = await readAsDataUrl(file);
      picked.value.push({
        id: `${file.name}-${file.size}-${Date.now()}-${index}`,
        name: file.name,
        mimeType: file.type,
        dataUrl,
      });
    }
  }

  function removeAttachment(id: string) {
    picked.value = picked.value.filter((image) => image.id !== id);
  }

  async function submit() {
    const value = text.value.trim();
    if ((!value && picked.value.length === 0) || isSending()) return;
    const attachments = picked.value.map(({ name, mimeType, dataUrl }) => ({
      name,
      mimeType,
      dataUrl,
    }));
    text.value = "";
    picked.value = [];
    await send(value, attachments);
  }

  return { text, picked, placeholder, hasInput, canSend, addFiles, removeAttachment, submit };
}
